def squash(s: str) -> str:
    result = []
    i = 0
    n = len(s)

    while i < n:
        j = i + 1
        while j < n and s[j] == s[i]:
            j += 1

        c = s[i]
        length = j - i
        escaped = "\\" + c if c.isdigit() or c == "\\" else c

        if length >= 3:
            result.append(str(length))
            result.append(escaped)
        else:
            result.append(escaped * length)

        i = j

    return "".join(result)
